-- Actual PG component fixtures only. All triggers enabled; no model/provider calls.
BEGIN;
CREATE TEMP TABLE examiner_checks(name text PRIMARY KEY);
CREATE FUNCTION pg_temp.examiner_assert(name text,value boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'examiner quality assertion failed: %',name; END IF; INSERT INTO examiner_checks VALUES(name); END $$;
CREATE FUNCTION pg_temp.examiner_reject(name text,statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE rejected boolean:=false; BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF position(expected IN SQLERRM)=0 THEN RAISE EXCEPTION 'unexpected rejection for %: %',name,SQLERRM; END IF; rejected:=true; END; IF NOT rejected THEN RAISE EXCEPTION 'missing rejection: %',name; END IF; INSERT INTO examiner_checks VALUES(name); END $$;
CREATE TEMP TABLE examiner_fixtures(name text PRIMARY KEY,customer_id uuid,source_id text,run_key text,audit_id uuid,source_at timestamptz);
CREATE FUNCTION pg_temp.examiner_fixture(label text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE c uuid:=gen_random_uuid(); conv uuid:=gen_random_uuid(); src uuid:=gen_random_uuid(); r text:='live:rollback:'||gen_random_uuid(); when_at timestamptz;
BEGIN
 SELECT greatest(now(),last_created_at+interval '1 second') INTO when_at FROM public.sandy_examiner_live_cursors WHERE channel='web';
 INSERT INTO public.email_customers(id,display_name,google_drive_folder_status) VALUES(c,'Examiner component rollback fixture','excluded');
 INSERT INTO public.sandy_web_conversations(id,customer_id) VALUES(conv,c);
 INSERT INTO public.sandy_web_turns(id,conversation_id,customer_id,request_id,question,response,status,created_at) VALUES(src,conv,c,'rollback-examiner:'||src,'Component quality request only','A reversible internal draft; no external action has occurred.','completed',when_at);
 INSERT INTO public.sandy_examiner_live_runs(run_key,details) VALUES(r,jsonb_build_object('cutoff',when_at+interval '1 minute'));
 INSERT INTO examiner_fixtures VALUES(label,c,src::text,r,NULL,when_at);
END $$;
SELECT pg_temp.examiner_fixture('pass');SELECT pg_temp.examiner_fixture('issue');SELECT pg_temp.examiner_fixture('changed');SELECT pg_temp.examiner_fixture('unknown');SELECT pg_temp.examiner_fixture('historical');SELECT pg_temp.examiner_fixture('null_score');SELECT pg_temp.examiner_fixture('long_source');SELECT pg_temp.examiner_fixture('emoji_boundary');
UPDATE public.sandy_web_turns SET question=repeat('q',2998)||'😀'||repeat('x',40000),response=repeat('a',3499)||'😀'||repeat('y',10000)WHERE id::text=(SELECT source_id FROM examiner_fixtures WHERE name='long_source');
UPDATE public.sandy_web_turns SET question=repeat('q',2999)||'😀end',response=repeat('a',3498)||'😀end'WHERE id::text=(SELECT source_id FROM examiner_fixtures WHERE name='emoji_boundary');
CREATE FUNCTION pg_temp.examiner_prepare(f examiner_fixtures) RETURNS jsonb LANGUAGE sql AS $$ WITH actual AS(SELECT public.sandy_examiner_actual_source('web',f.source_id)AS source)SELECT public.sandy_prepare_examiner_review(f.run_key,'web',f.source_id,'7d19d3ec92fb2a8951d540db5f9684e150069f1371a86c1b139aeed3f24db933',public.sandy_examiner_source_witness(source)::text,jsonb_build_object('channel','web','question',public.sandy_examiner_utf16_prefix(source->>'question',3000),'answer',public.sandy_examiner_utf16_prefix(source->>'response',3500),'receipt','paired_web_turn','recentContext','[]'::jsonb,'continuation_joined',false)::text,true)FROM actual $$;
SELECT pg_temp.examiner_assert('closed cost-sensitive internal contract never asserts customer session or provider proof',is_mutation AND NOT api_exposed AND NOT ui_exposed AND NOT ai_exposed AND NOT verified AND input_schema->'properties'='{}'::jsonb AND handler='internal:agent.reliability.interaction.review@1.0.0' AND (error_contract->>'sensitive')::boolean AND (error_contract->>'consumes_model_resources')::boolean AND error_contract->'auth_user_id'='null'::jsonb AND NOT(error_contract->>'qualitative_pass_is_external_execution_proof')::boolean) FROM public.sandy_operation_registry WHERE operation='agent.reliability.interaction.review';
SELECT pg_temp.examiner_assert('receipt RLS and narrow service RPC ACLs',(SELECT relrowsecurity FROM pg_class WHERE oid='public.sandy_examiner_quality_audit'::regclass) AND NOT has_table_privilege('authenticated','public.sandy_examiner_quality_audit','SELECT') AND NOT has_table_privilege('service_role','public.sandy_examiner_quality_audit','INSERT') AND NOT has_table_privilege('service_role','public.sandy_examiner_quality_audit','UPDATE') AND has_function_privilege('service_role','public.sandy_prepare_examiner_review(text,text,text,text,text,text,boolean)','EXECUTE') AND NOT has_function_privilege('anon','public.sandy_finish_examiner_review(uuid,boolean,text,text,text,text,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.sandy_examiner_actual_source(text,text)','EXECUTE'));
SELECT pg_temp.examiner_assert('every original fixture source and review trigger stays enabled',NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid IN('public.sandy_web_turns'::regclass,'public.sandy_whatsapp_messages'::regclass,'public.sandy_examiner_live_reviews'::regclass)AND NOT tgisinternal AND tgenabled='D'));
SELECT pg_temp.examiner_reject('wrong exact runtime source cannot claim',format('SELECT public.sandy_prepare_examiner_review(%L,''web'',%L,%L,''{}'',''{}'',true)',run_key,source_id,repeat('f',64)),'examiner_fixed_source_profile_required')FROM examiner_fixtures WHERE name='pass';
SELECT pg_temp.examiner_reject('fabricated run cannot claim',format('SELECT public.sandy_prepare_examiner_review(%L,''web'',%L,%L,''{}'',''{}'',true)','live:invented',source_id,'7d19d3ec92fb2a8951d540db5f9684e150069f1371a86c1b139aeed3f24db933'),'examiner_actual_running_run_required')FROM examiner_fixtures WHERE name='pass';
SELECT pg_temp.examiner_reject('actual source customer cannot be replaced in serialized snapshot',format('SELECT public.sandy_prepare_examiner_review(%L,''web'',%L,%L,%L,''{}'',true)',run_key,source_id,'7d19d3ec92fb2a8951d540db5f9684e150069f1371a86c1b139aeed3f24db933',(public.sandy_examiner_source_witness(public.sandy_examiner_actual_source('web',source_id))||jsonb_build_object('customer_id',gen_random_uuid()))::text),'examiner_actual_source_snapshot_changed')FROM examiner_fixtures WHERE name='pass';
UPDATE examiner_fixtures f SET audit_id=(pg_temp.examiner_prepare(f)->>'id')::uuid WHERE name<>'historical';
SELECT pg_temp.examiner_assert('actual source run customer and NULL Auth scope bind before model',a.state='started' AND a.model_request_planned AND a.customer_id=f.customer_id AND a.source_id=f.source_id AND a.run_key=f.run_key AND a.auth_user_id IS NULL AND a.source_snapshot->>'question'='Component quality request only')FROM examiner_fixtures f JOIN public.sandy_examiner_quality_audit a ON a.id=f.audit_id WHERE name='pass';
SELECT pg_temp.examiner_assert('source over32KB admits bounded SHA witness and preserves full actual snapshot',octet_length(a.source_snapshot::text)>32768 AND octet_length(public.sandy_examiner_source_witness(a.source_snapshot)::text)<2048 AND a.context->>'question'=repeat('q',2998)||'😀'AND a.context->>'answer'=repeat('a',3499))FROM examiner_fixtures f JOIN public.sandy_examiner_quality_audit a ON a.id=f.audit_id WHERE name='long_source';
SELECT pg_temp.examiner_assert('UTF16 boundary prefixes never include half of a nonBMP scalar',a.context->>'question'=repeat('q',2999)AND a.context->>'answer'=repeat('a',3498)||'😀'AND public.sandy_examiner_utf16_prefix(repeat('q',2998)||'😀end',3000)=repeat('q',2998)||'😀'AND public.sandy_examiner_utf16_prefix(repeat('a',3499)||'😀end',3500)=repeat('a',3499))FROM examiner_fixtures f JOIN public.sandy_examiner_quality_audit a ON a.id=f.audit_id WHERE name='emoji_boundary';
SELECT pg_temp.examiner_assert('witness preserves NULL versus empty UTF8 text',(public.sandy_examiner_source_witness('{"question":null,"response":""}') ->'question')='null'::jsonb AND public.sandy_examiner_source_witness('{"question":null,"response":""}')->'response'->>'sha256'='e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');
SELECT pg_temp.examiner_reject('same source cannot consume another model request',format('SELECT pg_temp.examiner_prepare(f) FROM examiner_fixtures f WHERE name=%L','unknown'),'examiner_source_outcome_requires_reconciliation');
SELECT pg_temp.examiner_reject('receipt scope immutable',format('UPDATE public.sandy_examiner_quality_audit SET state=''unknown'',customer_id=%L,error=''examiner_source_outcome_requires_reconciliation'',finished_at=now() WHERE id=%L',gen_random_uuid(),audit_id),'examiner_receipt_scope_immutable')FROM examiner_fixtures WHERE name='unknown';
SELECT pg_temp.examiner_reject('bare quality success without provider response is refused',format('SELECT public.sandy_finish_examiner_review(%L,false,''pass'',''useful_draft'',%L,NULL,NULL)',audit_id,'{"status":"evaluated","model":"gpt-6-astra","receipt":"paired_web_turn","quality_score":5,"reason_summary":"A qualitative model opinion only"}'),'examiner_actual_model_quality_receipt_required')FROM examiner_fixtures WHERE name='pass';
SELECT pg_temp.examiner_reject('planned request cannot claim not_run',format('SELECT public.sandy_finish_examiner_review(%L,false,''needs_review'',''actual_outcome_not_independently_verified'',%L,NULL,NULL)',audit_id,'{"status":"not_run","receipt":"paired_web_turn"}'),'examiner_unavailable_quality_cannot_claim_success')FROM examiner_fixtures WHERE name='pass';
SELECT pg_temp.examiner_reject('evaluated score must be JSON number or null, never string',format('SELECT public.sandy_finish_examiner_review(%L,false,''pass'',''useful_draft'',%L,''resp_component_not_provider_test'',%L)',audit_id,'{"status":"evaluated","model":"gpt-6-astra","receipt":"paired_web_turn","quality_score":"5","reason_summary":"A qualitative opinion only"}',repeat('a',64)),'examiner_actual_model_quality_receipt_required')FROM examiner_fixtures WHERE name='pass';
SELECT pg_temp.examiner_assert('JSON null quality score remains valid and explicitly unknown',(public.sandy_finish_examiner_review(audit_id,false,'needs_review','insufficient_context','{"status":"evaluated","model":"gpt-6-astra","receipt":"paired_web_turn","quality_score":null,"reason_summary":"Insufficient quality evidence"}','resp_component_not_model_test',repeat('c',64))->'review'->'quality_score')='null'::jsonb)FROM examiner_fixtures WHERE name='null_score';
SELECT pg_temp.examiner_assert('qualitative pass preserved with actual scoped internal record',(public.sandy_finish_examiner_review(audit_id,false,'pass','useful_draft','{"status":"evaluated","model":"gpt-6-astra","receipt":"paired_web_turn","quality_score":5,"reason_summary":"A qualitative model opinion only"}','resp_rollback_fixture_not_model_test',repeat('a',64))->'review'->>'quality_score')='5')FROM examiner_fixtures WHERE name='pass';
SELECT pg_temp.examiner_assert('pass never creates evidence of external execution',r.verdict='pass' AND r.customer_id=f.customer_id AND r.run_key=f.run_key AND a.state='succeeded' AND NOT EXISTS(SELECT 1 FROM public.sandy_evolution_cases WHERE case_key='examiner:live:web:'||f.source_id))FROM examiner_fixtures f JOIN public.sandy_examiner_quality_audit a ON a.id=f.audit_id JOIN public.sandy_examiner_live_reviews r ON r.id=a.review_id WHERE f.name='pass';
SELECT pg_temp.examiner_reject('completed final receipt cannot duplicate review',format('SELECT public.sandy_finish_examiner_review(%L,false,''pass'',''duplicate'',''{}'',NULL,NULL)',audit_id),'examiner_started_finish_claim_required')FROM examiner_fixtures WHERE name='pass';
SELECT pg_temp.examiner_assert('saved review reused without new paid claim',(pg_temp.examiner_prepare(f)->'existing_review'->>'review_id')=(SELECT review_id::text FROM public.sandy_examiner_quality_audit WHERE id=f.audit_id))FROM examiner_fixtures f WHERE name='pass';
SELECT pg_temp.examiner_assert('potential issue atomically stores review and approval-required investigation',(public.sandy_finish_examiner_review(audit_id,false,'potential_issue','conflicting_response','{"status":"evaluated","model":"gpt-6-astra","receipt":"paired_web_turn","quality_score":2.0,"reason_summary":"A possible contradiction needs separate investigation"}','resp_rollback_fixture_not_model_test',repeat('b',64))->>'ok')::boolean)FROM examiner_fixtures WHERE name='issue';
SELECT pg_temp.examiner_assert('integral JSON number representation normalizes to integer quality score',public.sandy_examiner_quality_result(a.review_id,true)->'quality_score'='2'::jsonb)FROM examiner_fixtures f JOIN public.sandy_examiner_quality_audit a ON a.id=f.audit_id WHERE f.name='issue';
SELECT pg_temp.examiner_assert('investigation remains unverified and undeployed',e.status='discovered' AND e.approval_required AND e.risk_tier='unassessed' AND e.deployment_reference IS NULL AND e.independent_verification='{}'::jsonb AND e.source_type='sandy_examiner_live_reviews' AND e.source_reference='web:'||f.source_id)FROM examiner_fixtures f JOIN public.sandy_evolution_cases e ON e.case_key='examiner:live:web:'||f.source_id WHERE f.name='issue';
SELECT pg_temp.examiner_assert('original actual finding trigger retained',EXISTS(SELECT 1 FROM public.sandy_operational_faults WHERE fault_key='examiner:web:'||f.source_id AND fault_type='conflicting_response'))FROM examiner_fixtures f WHERE f.name='issue';
UPDATE public.sandy_web_turns SET question='The customer edited the source during model review' WHERE id::text=(SELECT source_id FROM examiner_fixtures WHERE name='changed');
SELECT pg_temp.examiner_reject('changed actual source cannot be finalized as old context',format('SELECT public.sandy_finish_examiner_review(%L,false,''needs_review'',''actual_outcome_not_independently_verified'',%L,NULL,NULL)',audit_id,'{"status":"judge_unavailable","receipt":"paired_web_turn"}'),'examiner_source_changed_reconcile')FROM examiner_fixtures WHERE name='changed';
SELECT pg_temp.examiner_assert('source change leaves final writes atomic',NOT EXISTS(SELECT 1 FROM public.sandy_examiner_live_reviews WHERE channel='web'AND source_id=f.source_id)AND NOT EXISTS(SELECT 1 FROM public.sandy_evolution_cases WHERE case_key='examiner:live:web:'||f.source_id))FROM examiner_fixtures f WHERE name='changed';
SELECT pg_temp.examiner_assert('unknown result stays durable without a claimed quality verdict',(public.sandy_finish_examiner_review(audit_id,true,NULL,NULL,NULL,NULL,NULL)->>'reconciliation_required')::boolean)FROM examiner_fixtures WHERE name='unknown';
CREATE TEMP TABLE examiner_cross_run(run_key text);
WITH added AS(INSERT INTO public.sandy_examiner_live_runs(run_key,details)SELECT 'live:rollback-cross:'||gen_random_uuid(),jsonb_build_object('cutoff',source_at+interval '1 minute')FROM examiner_fixtures WHERE name='unknown' RETURNING run_key)INSERT INTO examiner_cross_run SELECT run_key FROM added;
SELECT pg_temp.examiner_reject('another run ID cannot retry unknown paid source',format('SELECT public.sandy_prepare_examiner_review(%L,''web'',%L,%L,%L,%L,true)',r.run_key,f.source_id,'7d19d3ec92fb2a8951d540db5f9684e150069f1371a86c1b139aeed3f24db933',public.sandy_examiner_source_witness(public.sandy_examiner_actual_source('web',f.source_id))::text,'{}'),'examiner_source_outcome_requires_reconciliation')FROM examiner_cross_run r CROSS JOIN examiner_fixtures f WHERE f.name='unknown';
INSERT INTO public.sandy_examiner_live_reviews(channel,source_id,source_at,customer_id,run_key,verdict,reason,judge_evidence)SELECT 'web',source_id,source_at,customer_id,run_key,'unverifiable','no_verified_outcome','{"status":"not_run","receipt":"unavailable"}'FROM examiner_fixtures WHERE name='historical';
SELECT pg_temp.examiner_assert('historical unknown model attempt is NULL rather than invented',(pg_temp.examiner_prepare(f)->'existing_review'->'model_request_attempted')='null'::jsonb AND NOT EXISTS(SELECT 1 FROM public.sandy_examiner_quality_audit WHERE channel='web'AND source_id=f.source_id))FROM examiner_fixtures f WHERE name='historical';
CREATE TEMP TABLE examiner_whatsapp(id text,run_key text,audit_id uuid);
WITH inserted AS(INSERT INTO public.sandy_whatsapp_messages(meta_message_id,phone_number_id,sender_wa_id,direction,message_type,body,created_at)SELECT 'rollback-examiner:'||gen_random_uuid(),'rollback-unmapped',NULL,'inbound','component','Unmapped component question only',greatest(now(),last_created_at+interval '1 second')FROM public.sandy_examiner_live_cursors WHERE channel='whatsapp'RETURNING id,created_at),added_run AS(INSERT INTO public.sandy_examiner_live_runs(run_key,details)SELECT 'live:rollback-wa:'||gen_random_uuid(),jsonb_build_object('cutoff',created_at+interval '1 minute')FROM inserted RETURNING run_key)INSERT INTO examiner_whatsapp SELECT inserted.id::text,added_run.run_key,NULL FROM inserted CROSS JOIN added_run;
UPDATE examiner_whatsapp w SET audit_id=(public.sandy_prepare_examiner_review(run_key,'whatsapp',id,'7d19d3ec92fb2a8951d540db5f9684e150069f1371a86c1b139aeed3f24db933',public.sandy_examiner_source_witness(public.sandy_examiner_actual_source('whatsapp',id))::text,'{"channel":"whatsapp","question":"Unmapped component question only","answer":"","receipt":"unavailable","recentContext":[],"continuation_joined":false}',false)->>'id')::uuid;
SELECT pg_temp.examiner_assert('unmapped WhatsApp never invents customer or model work',a.customer_id IS NULL AND a.auth_user_id IS NULL AND NOT a.model_request_planned AND a.state='started')FROM examiner_whatsapp w JOIN public.sandy_examiner_quality_audit a ON a.id=w.audit_id;
SELECT pg_temp.examiner_assert('no-model unmapped result remains unverifiable and NULL customer',(public.sandy_finish_examiner_review(audit_id,false,'unverifiable','no_verified_outcome','{"status":"not_run","receipt":"unavailable"}',NULL,NULL)->'review'->'customer_id')='null'::jsonb)FROM examiner_whatsapp;
SELECT pg_temp.examiner_assert('one unknown receipt cannot be reset or rewritten',bool_and(state='unknown'AND review_id IS NULL))FROM public.sandy_examiner_quality_audit WHERE id=(SELECT audit_id FROM examiner_fixtures WHERE name='unknown');
SELECT jsonb_build_object('status','pass','component_checks',count(*),'real_provider_calls',0,'real_model_calls',0,'all_changes_rolled_back',true,'all_production_triggers_enabled',NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid IN('public.sandy_web_turns'::regclass,'public.sandy_whatsapp_messages'::regclass,'public.sandy_examiner_live_reviews'::regclass)AND NOT tgisinternal AND tgenabled='D'),'fixture_customer_ids',(SELECT jsonb_agg(customer_id)FROM examiner_fixtures),'fixture_whatsapp_ids',(SELECT jsonb_agg(id)FROM examiner_whatsapp),'fixture_run_keys',(SELECT jsonb_agg(run_key)FROM(SELECT run_key FROM examiner_fixtures UNION ALL SELECT run_key FROM examiner_whatsapp UNION ALL SELECT run_key FROM examiner_cross_run)r),'uncommitted_http_outbox_ids',(SELECT coalesce(jsonb_agg(id),'[]')FROM net.http_request_queue WHERE pg_xact_status(xmin::text::xid8)='in progress'),'real_customer_execution_tested',false)AS examiner_quality_evidence FROM examiner_checks;
ROLLBACK;
